  acl    = "private"
  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
  tags = { Name = "alb-access-logs" }
}

resource "aws_s3_bucket_public_access_block" "alb_logs_block" {
  bucket = aws_s3_bucket.alb_logs.id
  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}

resource "aws_lb" "api_alb" {
  # already defined above – this block merges with previous using same name; duplicate omitted
}

resource "aws_lb_listener" "https_listener" {
  # already defined above – duplicate omitted
}

resource "aws_lb_target_group" "api_tg" {
  # already defined above – duplicate omitted
}

# Grant ALB permission to write logs
resource "aws_lb_listener_certificate" "alb_cert" {
  listener_arn    = aws_lb_listener.https_listener.arn
  certificate_arn = var.acm_certificate_arn
}

resource "aws_lb_target_group_attachment" "tg_attachment" {
  # attachment managed by ECS service; no explicit resource needed
}

# IAM role for RDS monitoring
resource "aws_iam_role" "rds_monitor_role" {
  name = "api-rds-monitor"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy" "rds_monitor_policy" {
  name = "rds-monitor-policy"
  role = aws_iam_role.rds_monitor_role.id
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Action = [
        "logs:CreateLogGroup",
        "logs:CreateLogStream",
        "logs:PutLogEvents",
        "logs:PutRetentionPolicy"
      ],
      Resource = "*"
    }]
  })
}

resource "aws_db_instance" "api_rds" {
  # already defined above – duplicate omitted
}

# Export ALB access logs
resource "aws_lb" "api_alb" {
  access_logs {
    bucket = aws_s3_bucket.alb_logs.bucket
    enabled = true
    prefix = "alb"
  }
}

# Random suffix for bucket name uniqueness
resource "random_pet" "suffix" {}

# Output values
output "alb_dns_name" {
  value = aws_lb.api_alb.dns_name
}

output "ecr_repository_url" {
  value = aws_ecr_repository.api_repo.repository_url
}

output "rds_endpoint" {
  value = aws_db_instance.api_rds.endpoint
}

original_files.terraform/variables.tf:
# Input variables for API deployment
variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidrs" {
  description = "List of CIDR blocks for public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "private_subnet_cidrs" {
  description = "List of CIDR blocks for private subnets"
  type        = list(string)
  default     = ["10.0.101.0/24", "10.0.102.0/24"]
}

variable "acm_certificate_arn" {
  description = "ARN of ACM certificate for ALB HTTPS"
  type        = string
}

variable "alb_log_bucket_name" {
  description = "S3 bucket name for ALB access logs"
  type        = string
  default     = "api-alb-logs-${random_pet.suffix.id}"
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "rds_allocated_storage" {
  description = "Allocated storage (GiB) for RDS"
  type        = number
  default     = 20
}

variable "rds_db_name" {
  description = "Initial DB name"
  type        = string
  default     = "apidb"
}

variable "rds_username" {
  description = "Master username for RDS"
  type        = string
  default     = "admin"
}

variable "rds_password" {
  description = "Master password for RDS"
  type        = string
  sensitive   = true
}

variable "kms_key_id" {
  description = "KMS key ID for encrypting logs and storage"
  type        = string
}

